template <typename T>
auto tag(T*) -> typename T::tag_type;
void tag(...);
// Для int* в непосредственном контексте нельзя получить int::tag_type.
// Шаблонный кандидат отпадает; для этого вызова остаётся вариант с многоточием.

#include <type_traits>

template <typename T>
auto floating_copy(T value)
    -> std::enable_if_t<std::is_floating_point_v<T>, T> {
  return value;
}
// floating_copy(1.5) допустим, floating_copy(1) не имеет подходящей перегрузки.

std::map<int, int> scores{{4, 12}};
auto it = scores.find(9);
if (it != scores.end()) {
  std::cout << it->second;
}
// Ключ 9 не добавлен; size() == 1.

std::map<int, int> scores{{4, 12}};
scores.try_emplace(4, 18); // осталось 12
scores.insert_or_assign(4, 25); // стало 25; size() == 1

std::vector<int> numbers{4};
numbers.reserve(12); // size() == 1
numbers.resize(3, 8); // элементы: 4, 8, 8
// capacity() не обязана быть ровно 12.

std::vector<int> numbers{4, 8};
auto it = std::find(numbers.begin(), numbers.end(), 8);
if (it != numbers.end()) {
  std::cout << *it; // 8
}

std::vector<int> numbers{4, 8, 12};
auto next = numbers.erase(numbers.begin());
// next указывает на 8; если удалили последний элемент, получили бы end().

std::vector<int> numbers{4, 7, 4};
auto tail = std::remove(numbers.begin(), numbers.end(), 4);
// size() всё ещё 3; сохраняемый префикс содержит 7.
numbers.erase(tail, numbers.end()); // остался один элемент

int number = 18;
const int* view = &number;
number = 25;
// Пока number жив, *view читает тот же объект и даст 25.
// Копии указателя не являются отдельными копиями number.

std::string label = "ready";
const char* first = label.c_str();
// first[0] читается как 'r', пока label жив и указатель не инвалидирован.
// Другая строка с тем же текстом не становится владельцем first.

auto owner = std::make_unique<int>(18);
const int& view = *owner;
// view позволяет читать объект, но не становится его владельцем.
// Функция void inspect(const int&) вызывается как inspect(*owner).

{
  std::vector<int> buffer(24);
  use(buffer);
}
// При обычном выходе из блока деструктор buffer освободит его хранилище.
// Для чужого невладеющего указателя такое освобождение не выполняется.

struct Shape {
  virtual int corners() const { return 0; }
  virtual ~Shape() = default;
};
struct Triangle : Shape {
  int corners() const override { return 3; }
};
Triangle original;
Shape copy = original;
const Shape& alias = original;
// copy.corners() == 0; alias.corners() == 3.

struct Device {
  virtual int code() const { return 4; }
  virtual ~Device() = default;
};
struct Sensor : Device {
  int code() const override { return 9; }
};
Sensor sensor;
const Device& device = sensor;
// device.code() == 9: ссылка обозначает Sensor.

struct Resource {
  virtual ~Resource() = 0;
};
Resource::~Resource() = default;
struct File : Resource {};
std::unique_ptr<Resource> owner = std::make_unique<File>();
// При уничтожении owner вызываются ~File(), затем ~Resource().

template <typename... Ts>
void relay(Ts... values) {
  target(values...);
}
// relay(8, 5) вызывает target(8, 5).
// Целевой вызов должен быть допустим для этих аргументов.

template <typename... Ts>
auto total(Ts... values) {
  return (... + values);
}
// total(3, 8, 5): (3 + 8) + 5.
// Для вычитания направление меняет результат.

template <typename... Ts>
auto product(Ts... values) {
  return (1 * ... * values);
}
// product() даёт 1, product(4, 5) — (1 * 4) * 5.

struct Box { int weight; };
Box box{42};
auto& weight = std::invoke(&Box::weight, box);
weight = 50; // меняет box.weight

struct Meter { double value; };
using R = std::invoke_result_t<decltype(&Meter::value), const Meter&>;
// R — const double&

std::vector<int> values{3, 6, 9};
auto it = std::lower_bound(values.begin(), values.end(), 5);
// it указывает на 6; ключа 5 в наборе нет

int values[]{4, 8};
std::span<const int> view = values;
values[1] = 12;
// view[1] теперь 12; данные общие

struct Row { int rank; };
std::vector<Row> rows{{6}, {2}};
std::ranges::sort(rows, {}, &Row::rank);
// Записи упорядочены по rank; {} выбирает компаратор по умолчанию.

auto owner = std::make_unique<int>(18);
const int* view = owner.get();
*owner = 25;
// *view == 25: объект один, get() не создал копию.
// Вручную вызывать delete view нельзя: ресурс принадлежит owner.

auto first = std::make_unique<int>(18);
int* view = first.get();
auto second = std::move(first);
// first == nullptr; second.get() == view; *second == 18.
// view не владеет объектом; его жизнь теперь контролирует second.

auto owner = std::make_unique<int>(18);
owner.reset();
// owner.get() == nullptr; прежний int уже удалён.
owner = std::make_unique<int>(25); // новый независимый объект

int main() {
  int height = 7;
  int wider = height + 5;
  (void)wider;
}
// height обозначает объект; height + 5 вычисляет новое значение int.

int main() {
  int length = 10;
  int& left = length;
  int& right = left;
  right = 13;
}
// left и right по-прежнему обозначают length, а не отдельные копии.

void ClampToZero(int& amount) {
  if (amount < 0) {
    amount = 0;
  }
}

int main() {
  int debt = -4;
  ClampToZero(debt);
}
// amount обозначает debt; вызов меняет int вызывающего кода.

